import React,{useEffect,useRef,useState} from 'react'; import { Link } from 'react-router-dom'; import { FiArrowUpRight } from 'react-icons/fi'; import './CaseStudies.css';
import physio from '../Assets/PhysioSync.png'; import meals from '../Assets/mealmaster.jpg'; import fresh from '../Assets/freshpicks.png';
const work=[{image:physio,title:'PhysioSync',type:'Mobile App Development',copy:'An intelligent physiotherapy experience that helps people perform movements with more confidence and better feedback.'},{image:meals,title:'MealMaster CRM',type:'Web Development',copy:'A practical, elegant CRM platform that helps food service teams manage customers, orders, and growth.'},{image:fresh,title:'Freshpicks',type:'Web Development',copy:'A community-driven platform that makes it easier to discover and support local farmers markets.'}];
const CaseStudies=()=>{const sectionRef=useRef(null);const [visible,setVisible]=useState(false);useEffect(()=>{const observer=new IntersectionObserver(([entry])=>{if(entry.isIntersecting){setVisible(true);observer.disconnect()}},{threshold:.15});if(sectionRef.current)observer.observe(sectionRef.current);return()=>observer.disconnect()},[]);return <section className={`case-studies ${visible?'is-visible':''}`} ref={sectionRef}><div className="case-heading"><div><span className="mini-rule"/><p className="section-kicker">Selected work / 2026</p><h2>Ideas made<br/><b>real.</b></h2></div><p>From a first conversation to a product people return to, here are a few stories we’re proud to have shaped.</p></div><div className="case-list">{work.map((item,index)=><article className={`case-card case-${index}`} key={item.title}><div className="case-image"><img src={item.image} alt={item.title}/><span>{String(index+1).padStart(2,'0')}</span></div><div className="case-content"><p className="case-type">{item.type}</p><h3>{item.title}</h3><p>{item.copy}</p><Link to="/projects">View case study <FiArrowUpRight/></Link></div></article>)}</div><Link className="all-work" to="/projects">Explore all projects <FiArrowUpRight/></Link></section>};
export default CaseStudies;
